import Foundation

// MARK: - Overcoming Doubt Content Expansion (Entries 9–20)

extension ContentLibrary {

    static let overcomingDoubtContentExpansion: [DayContent] = [
        DayContent(
            scriptureReference: "James 1:5-6",
            scriptureText: "If any of you lacks wisdom, you should ask God, who gives generously to all without finding fault, and it will be given to you. But when you ask, you must believe and not doubt, because the one who doubts is like a wave of the sea, blown and tossed by the wind.",
            devotionalTitle: "Ask Without Shame",
            devotionalText: "God doesn't find fault when you come to Him with questions. He gives wisdom generously — not grudgingly, not with a lecture about why you should already know. The invitation is to ask. The challenge is to ask in faith, not letting doubt toss you around like waves. Doubt makes you unstable. Faith anchors you. Come to God with your questions today — He's not bothered by them.",
            prayerText: "Lord, I come to You lacking wisdom. I have questions I can't answer on my own. Thank You for giving generously without finding fault. Anchor me in faith as I ask. Don't let doubt blow me around. I believe You have answers — help me receive them with a steady heart. In Jesus' name, amen.",
            reflectionPrompt: "What question have you been afraid to bring to God because you thought He'd find fault?",
            actionSteps: ["Bring one honest question to God in prayer and trust Him to answer generously", "Write down a question you've been wrestling with and commit it to God"]
        ),
        DayContent(
            scriptureReference: "Isaiah 41:10",
            scriptureText: "So do not fear, for I am with you; do not be dismayed, for I am your God. I will strengthen you and help you; I will uphold you with my righteous right hand.",
            devotionalTitle: "Doubt's Antidote: Presence",
            devotionalText: "Fear and dismay are doubt's companions. When you doubt God's goodness or His plan, fear follows quickly. But God's response to doubt isn't a theological argument — it's His presence. 'I am with you. I am your God.' He doesn't prove Himself through logic alone; He proves Himself by showing up. The strongest antidote to doubt is experiencing God's presence in the middle of it.",
            prayerText: "Lord, I will not fear because You are with me. I will not be dismayed because You are my God. When doubt tells me I'm alone, Your presence tells me otherwise. Strengthen me, help me, uphold me. I don't need all the answers — I need You. And You are here. In Jesus' name, amen.",
            reflectionPrompt: "When has God's presence been more convincing than any argument?",
            actionSteps: ["Sit in God's presence for 10 minutes without asking for anything — just be with Him", "When doubt rises today, respond with 'God is with me' instead of trying to argue yourself out of it"]
        ),
        DayContent(
            scriptureReference: "Psalm 73:16-17",
            scriptureText: "When I tried to understand all this, it troubled me deeply till I entered the sanctuary of God; then I understood their final destiny.",
            devotionalTitle: "Understanding Comes in His Presence",
            devotionalText: "Asaph was troubled by doubt — specifically, why the wicked prospered while the faithful suffered. He couldn't think his way to an answer. But when he entered God's sanctuary, perspective came. Some doubts can't be resolved by thinking harder. They're resolved by drawing closer. When understanding eludes you in your head, try seeking it in His presence. Worship often answers what logic cannot.",
            prayerText: "Lord, I've been troubled by things I can't understand. I've tried to think my way through it, and it only made me more confused. So I enter Your sanctuary instead. Give me perspective in Your presence that I couldn't find on my own. Let worship answer what my mind cannot. In Jesus' name, amen.",
            reflectionPrompt: "What doubt has gotten worse the more you've tried to think your way through it?",
            actionSteps: ["Instead of analyzing your doubt today, spend time in worship and see if perspective shifts", "Visit a church, chapel, or quiet place and bring your unresolved questions into God's presence"]
        ),
        DayContent(
            scriptureReference: "2 Timothy 1:12",
            scriptureText: "That is why I am suffering as I am. Yet this is no cause for shame, because I know whom I have believed, and am convinced that he is able to guard what I have entrusted to him until that day.",
            devotionalTitle: "Know Whom You Believe",
            devotionalText: "Paul didn't say 'I know what I believe.' He said 'I know whom I have believed.' The foundation of faith isn't a perfect theology — it's a personal relationship. You may not have answers to every question, but you know Jesus. And knowing Him is enough to be convinced He can guard what you've entrusted to Him. Doubt attacks your ideas. Relationship with Jesus anchors your soul.",
            prayerText: "Lord, I may not have all the answers, but I know You. And knowing You is my anchor. I am convinced that You are able to guard everything I've entrusted to You. My faith isn't in perfect understanding — it's in a perfect Savior. I trust You with what I don't know. In Jesus' name, amen.",
            reflectionPrompt: "Do you know Jesus personally, or just know about Him? What's the difference in your experience?",
            actionSteps: ["Write down what you know to be true about Jesus from your personal experience with Him", "Entrust one specific doubt to Jesus today and trust Him to guard it"]
        ),
        DayContent(
            scriptureReference: "Luke 7:19-23",
            scriptureText: "So he sent them to the Lord to ask, 'Are you the one who is to come, or should we expect someone else?' ... So he replied to the messengers, 'Go back and report to John what you have seen and heard.'",
            devotionalTitle: "Even John the Baptist Doubted",
            devotionalText: "John the Baptist — the one who baptized Jesus, who saw the Spirit descend, who declared 'Behold the Lamb of God' — sent messengers from prison asking 'Are you really the one?' If John could doubt, so can you. And Jesus didn't shame him. He pointed to evidence: the blind see, the lame walk, the good news is preached. When doubt hits, look at the evidence. What has God done?",
            prayerText: "Jesus, if John the Baptist could doubt from his prison cell, I don't need to be ashamed of my doubts. Point me to the evidence of Your work. Help me see what You've done, what You're doing, and what You've promised to do. My circumstances may feel like a prison, but Your works tell a different story. In Jesus' name, amen.",
            reflectionPrompt: "What evidence of God's work in your life can you point to when doubt creeps in?",
            actionSteps: ["Make a list of 5 things God has done in your life that you can point to as evidence", "When doubt comes today, read your evidence list instead of spiraling"]
        ),
        DayContent(
            scriptureReference: "Psalm 77:11-12",
            scriptureText: "I will remember the deeds of the Lord; yes, I will remember your miracles of long ago. I will consider all your works and meditate on all your mighty deeds.",
            devotionalTitle: "Remember What God Has Done",
            devotionalText: "Memory is one of the most powerful weapons against doubt. The psalmist was in distress — crying out, unable to sleep, wondering if God had forgotten him. His strategy? Remember. Look back at what God has done. Doubt thrives on amnesia. When you forget God's faithfulness, doubt fills the gap. But when you actively remember His deeds, faith revives. Your history with God is your ammunition against doubt.",
            prayerText: "Lord, I choose to remember. I will not forget what You've done — the miracles, the provisions, the rescues, the answers to prayer. When doubt tries to erase my memory of Your faithfulness, I will meditate on Your mighty deeds. My past with You proves my future is safe. In Jesus' name, amen.",
            reflectionPrompt: "What is the most powerful thing God has done in your life that you can remember right now?",
            actionSteps: ["Write a 'remembrance list' of 10 things God has done in your life", "Share one of these memories with someone to strengthen both your faith and theirs"]
        ),
        DayContent(
            scriptureReference: "Habakkuk 1:2-3",
            scriptureText: "How long, Lord, must I call for help, but you do not listen? Or cry out to you, 'Violence!' but you do not save? Why do you make me look at injustice? Why do you tolerate wrongdoing?",
            devotionalTitle: "Honest Questions Are Not Sin",
            devotionalText: "Habakkuk didn't whisper politely. He challenged God directly: How long? Why? These are the prayers of a man who trusts God enough to be angry at Him. Doubt expressed honestly before God is not sin — it's relationship. The prophets, psalmists, and even Jesus on the cross asked God hard questions. If you're afraid to voice your doubt, know this: God would rather hear your honest questions than your polished silence.",
            prayerText: "Lord, I bring You my honest questions. How long will this last? Why does this happen? I'm not being irreverent — I'm being real. You can handle my honesty. Meet me in my questions. I trust You enough to bring my doubt directly to You rather than hiding it. In Jesus' name, amen.",
            reflectionPrompt: "What honest question have you been afraid to ask God?",
            actionSteps: ["Write your hardest question to God and don't soften it — be raw and honest", "Read Habakkuk 1-3 and notice how God responds to honest questioning"]
        ),
        DayContent(
            scriptureReference: "John 6:67-69",
            scriptureText: "'You do not want to leave too, do you?' Jesus asked the Twelve. Simon Peter answered him, 'Lord, to whom shall we go? You have the words of eternal life. We have come to believe and to know that you are the Holy One of God.'",
            devotionalTitle: "Where Else Would You Go?",
            devotionalText: "Many followers left Jesus after hard teaching. He turned to the Twelve and asked if they wanted to leave too. Peter's answer wasn't 'I have no doubts.' It was 'Where else would we go?' Sometimes faith isn't about having zero questions. It's about recognizing that nothing else offers what Jesus offers. You might have doubts, but if you've tasted the words of eternal life, where else would you go?",
            prayerText: "Jesus, I may have questions, but where else would I go? You have the words of eternal life. Nothing else satisfies. No philosophy, no distraction, no alternative offers what You give. I choose to stay — not because I have no doubts, but because I have no better option. You are the Holy One of God. In Jesus' name, amen.",
            reflectionPrompt: "If you left faith behind, where would you actually go? What would you replace Jesus with?",
            actionSteps: ["Honestly consider the alternatives to faith and compare them to what Jesus offers", "Write Peter's declaration in your own words: 'Lord, I stay because...'"]
        ),
        DayContent(
            scriptureReference: "Romans 8:38-39",
            scriptureText: "For I am convinced that neither death nor life, neither angels nor demons, neither the present nor the future, nor any powers, neither height nor depth, nor anything else in all creation, will be able to separate us from the love of God that is in Christ Jesus our Lord.",
            devotionalTitle: "Doubt Cannot Separate You",
            devotionalText: "Paul lists everything that might threaten your connection to God — death, demons, the present, the future, powers. Notably absent from the list? Doubt. Your doubt does not separate you from God's love. It can't. Nothing in all creation can. Not your questions, not your struggles to believe, not your worst moments of uncertainty. You are held by a love that your doubt cannot break.",
            prayerText: "Lord, I am convinced that nothing — not even my doubt — can separate me from Your love. My questions don't push You away. My struggles to believe don't break Your hold on me. Thank You that Your love is stronger than my uncertainty. I rest in a love that nothing can break. In Jesus' name, amen.",
            reflectionPrompt: "Have you been afraid that your doubt might disqualify you from God's love? What does this passage say?",
            actionSteps: ["Read Romans 8:38-39 out loud, inserting 'not even my doubt' into the list", "Rest today in the security that God's love for you is not threatened by your questions"]
        ),
        DayContent(
            scriptureReference: "Mark 9:23",
            scriptureText: "'If you can?' said Jesus. 'Everything is possible for one who believes.'",
            devotionalTitle: "The Power of Even Small Faith",
            devotionalText: "The father said 'if you can.' Jesus echoed it back with surprise — 'If I can?' It's not a question of God's ability. The question is always about our belief. But here's the good news: Jesus didn't require perfect faith. The father believed imperfectly, and Jesus still acted. Everything is possible for one who believes — and even a mustard seed of belief is enough for God to work with. Your small faith accesses a big God.",
            prayerText: "Jesus, I believe — even if my faith feels small. I know the issue isn't Your ability; it's my belief. So I bring what little faith I have and ask You to work with it. Everything is possible for those who believe, and I choose to believe today — imperfectly, incompletely, but honestly. In Jesus' name, amen.",
            reflectionPrompt: "Have you been waiting for perfect faith before asking God for something? What if small faith is enough?",
            actionSteps: ["Ask God for something today with whatever faith you have — don't wait until your faith feels bigger", "Write 'Everything is possible for one who believes' where you'll see it this week"]
        ),
        DayContent(
            scriptureReference: "Lamentations 3:31-33",
            scriptureText: "For no one is cast off by the Lord forever. Though he brings grief, he will show compassion, so great is his unfailing love. For he does not willingly bring affliction or grief to the children of men.",
            devotionalTitle: "God Has Not Cast You Off",
            devotionalText: "In your darkest doubt, it can feel like God has abandoned you — cast you off permanently. But Jeremiah declares the truth: no one is cast off forever. The grief and difficulty you're experiencing is not God's rejection. His compassion is coming. His love is unfailing. He doesn't bring pain willingly or casually. If you feel far from God, you are not cast off. You are in a season, and compassion is on the way.",
            prayerText: "Lord, when I feel cast off, remind me that Your rejection is never permanent. Compassion is coming because Your love is unfailing. You don't bring grief willingly — You grieve with me. In this season of doubt, I trust that You haven't abandoned me. Bring Your compassion near. In Jesus' name, amen.",
            reflectionPrompt: "Have you interpreted a season of difficulty as God casting you off? What if compassion is just around the corner?",
            actionSteps: ["If you feel far from God, tell Him honestly and ask Him to show His compassion today", "Read Lamentations 3:19-33 and let the journey from despair to hope encourage you"]
        ),
        DayContent(
            scriptureReference: "Psalm 34:18",
            scriptureText: "The Lord is close to the brokenhearted and saves those who are crushed in spirit.",
            devotionalTitle: "Close in the Crushing",
            devotionalText: "Doubt often comes with heartbreak — broken expectations, crushed hopes, shattered assumptions about how God works. In those crushing moments, God doesn't stand at a distance waiting for you to figure it out. He draws close. The Lord is near to the brokenhearted. Your doubt may feel like distance from God, but the truth is the opposite: He is closest when you are most broken. You are not far from God. He is right here.",
            prayerText: "Lord, I am brokenhearted and crushed in spirit. But I believe You are close — closer than I feel, closer than my doubt tells me. Save me from the spiral of despair. Draw near to me as I draw near to You. In my brokenness, let me encounter Your nearness. In Jesus' name, amen.",
            reflectionPrompt: "Can you believe that God is closest to you right now, in your most broken moment?",
            actionSteps: ["Sit quietly and invite God's nearness instead of trying to solve your doubt intellectually", "Tell someone you trust about your doubt and let them pray for you — community carries what you can't"]
        ),
    ]
}
